#!/usr/bin/env python3
"""
运行时配置文件差异分析工具

发现源码树中的运行时配置文件，按格式解析有效配置项，
对比两个版本的配置差异。标准格式自动解析，非标准格式标记待 AI 分析。

支持的格式:
  JSON   (.json)              → json.loads 结构化对比
  INI    (.ini, .cfg)         → configparser KV 对比
  KV     (.conf, .conf)       → key value / key=value 行式对比
  其他   (.xml, .yaml, .toml) → 文本行对比
  非标准 (nginx, apache, pg)  → 标记 "需AI分析"

用法:
  # 单版本分析
  python3 config_diff_analyzer.py /path/to/project -o result.csv

  # 两版本对比
  python3 config_diff_analyzer.py /old /new -o diff.csv

  # 指定配置目录
  python3 config_diff_analyzer.py /old /new --conf-dirs conf,etc -o diff.csv

  # 只发现文件，不解析
  python3 config_diff_analyzer.py /path/to/project --discover-only -o discovery.csv

输出:
  单版本: 1 个 CSV 文件（配置项清单）
  两版本: 3 个 CSV 文件 (<output>, <output>_old.csv, <output>_new.csv)
"""

import argparse
import csv
import json
import os
import re
import subprocess
import sys

_CONF_EXTENSIONS = frozenset({
    ".conf", ".cfg", ".ini", ".json", ".toml", ".yaml", ".yml",
    ".xml", ".properties", ".opts",
})

_CONF_DIRS = frozenset({
    "conf", "etc", "config", "configs", "settings",
})

_SKIP_DIRS = frozenset({
    "test", "tests", "testing", "build", ".git", "node_modules",
    "vendor", "third_party", "dpdk", "deps", "doc", "docs",
    "licenses", "license", "assets", "static", "templates",
    "docker", "vagrant", "cmake", "commands", "scripts",
    "man", "examples", "share", "locale", "include",
    "lib", "lib64", "src", "bin", "sbin",
})

_JSON_EXTS = frozenset({".json"})
_INI_EXTS = frozenset({".ini", ".cfg"})
_KV_EXTS = frozenset({".conf", ".properties", ".opts"})
_YAML_EXTS = frozenset({".yaml", ".yml"})
_XML_EXTS = frozenset({".xml"})
_TOML_EXTS = frozenset({".toml"})

_KV_SPACE_RE = re.compile(r'^\s*([a-zA-Z_][\w.-]+)\s+(\S.*?)\s*$')
_KV_EQ_RE = re.compile(r'^\s*([a-zA-Z_][\w.-]+)\s*=\s*(.*?)\s*$')
_KV_COMMENT_VAL_RE = re.compile(r'^\s*#\s*([a-zA-Z_][\w.-]+)\s+(\S.*?)\s*$')
_KV_COMMENT_EQ_RE = re.compile(r'^\s*#\s*([a-zA-Z_][\w.-]+)\s*=\s*(.*?)\s*$')
_SECTION_RE = re.compile(r'^\s*\[([^\]]+)\]\s*$')

_NGINX_SIGNATURES = ["server {", "location {", "http {", "events {", "upstream {",
                     "worker_processes", "listen ", "server_name"]
_APACHE_SIGNATURES = ["<VirtualHost", "<Directory", "RewriteEngine", "AllowOverride"]
_PG_SIGNATURES = ["shared_buffers", "work_mem", "max_connections",
                  "wal_level", "listen_addresses"]


def _detect_format(filepath):
    ext = os.path.splitext(filepath)[1].lower()
    name = os.path.basename(filepath).lower()

    if name == "nginx.conf" or _has_signature(filepath, _NGINX_SIGNATURES):
        return "nginx"
    if _has_signature(filepath, _APACHE_SIGNATURES):
        return "apache"
    if name.startswith("postgresql") and name.endswith(".conf"):
        return "postgresql"
    if ext in _JSON_EXTS:
        return "json"
    if ext in _INI_EXTS:
        return "ini"
    if ext in _YAML_EXTS:
        return "yaml"
    if ext in _TOML_EXTS:
        return "toml"
    if ext in _XML_EXTS:
        return "xml"
    if ext in _KV_EXTS:
        return "kv"
    return "kv"


def _has_signature(filepath, sigs, max_lines=30):
    try:
        with open(filepath, "r", encoding="utf-8", errors="replace") as f:
            for i, line in enumerate(f):
                if i >= max_lines:
                    break
                for sig in sigs:
                    if sig in line:
                        return True
    except (IOError, OSError):
        pass
    return False


def discover_config_files(root, extra_dirs=None, extra_skip=None):
    results = []
    conf_dirs = set(_CONF_DIRS)
    skip_dirs = set(_SKIP_DIRS)
    if extra_dirs:
        conf_dirs.update(d.strip() for d in extra_dirs.split(",") if d.strip())
    if extra_skip:
        skip_dirs.update(d.strip() for d in extra_skip.split(",") if d.strip())

    for dirpath, dirnames, filenames in os.walk(root, followlinks=True):
        dirnames[:] = [d for d in dirnames if d not in skip_dirs and not d.startswith(".")]
        reldir = os.path.relpath(dirpath, root)

        for fname in filenames:
            ext = os.path.splitext(fname)[1].lower()
            if ext not in _CONF_EXTENSIONS:
                continue
            if fname.startswith("Makefile") or fname.startswith("CMakeLists"):
                continue

            fullpath = os.path.join(dirpath, fname)
            try:
                if os.path.getsize(fullpath) > 2 * 1024 * 1024:
                    continue
            except OSError:
                continue

            parts = reldir.split(os.sep) if reldir != "." else []
            in_conf_dir = any(p in conf_dirs for p in parts)
            is_root_conf = reldir == "." and ext in frozenset({".conf", ".ini", ".cfg"})

            priority = 1 if (in_conf_dir or is_root_conf) else 2

            fmt = _detect_format(fullpath)
            results.append({
                "path": fullpath,
                "relpath": os.path.join(reldir, fname) if reldir != "." else fname,
                "format": fmt,
                "priority": priority,
            })

    results.sort(key=lambda x: (x["priority"], x["relpath"]))
    return results


def parse_config(filepath, fmt):
    if fmt == "json":
        return _parse_json(filepath)
    if fmt == "ini":
        return _parse_ini(filepath)
    if fmt == "kv":
        return _parse_kv(filepath)
    if fmt == "yaml":
        return _parse_kv(filepath)
    if fmt == "toml":
        return _parse_kv(filepath)
    if fmt == "xml":
        return _parse_kv(filepath)
    return _parse_kv(filepath)


def _parse_json(filepath):
    items = []
    try:
        with open(filepath, "r", encoding="utf-8") as f:
            data = json.load(f)
        _flatten_json(data, [], items)
    except (json.JSONDecodeError, IOError):
        pass
    return items


def _flatten_json(obj, prefix, items):
    if isinstance(obj, dict):
        for k, v in obj.items():
            _flatten_json(v, prefix + [k], items)
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            _flatten_json(v, prefix + [str(i)], items)
    else:
        items.append({
            "key": ".".join(prefix),
            "value": str(obj),
            "active": True,
        })


def _parse_ini(filepath):
    items = []
    current_section = ""
    try:
        with open(filepath, "r", encoding="utf-8", errors="replace") as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith("#") or line.startswith(";"):
                    m = _KV_COMMENT_EQ_RE.match(line) or _KV_COMMENT_VAL_RE.match(line)
                    if m and _is_config_key(m.group(1), active=False):
                        items.append({
                            "key": f"{current_section}.{m.group(1)}" if current_section else m.group(1),
                            "value": m.group(2),
                            "active": False,
                        })
                    continue
                m = _SECTION_RE.match(line)
                if m:
                    current_section = m.group(1).strip()
                    continue
                m = _KV_EQ_RE.match(line)
                if m:
                    key = f"{current_section}.{m.group(1)}" if current_section else m.group(1)
                    items.append({"key": key, "value": m.group(2), "active": True})
    except IOError:
        pass
    return items


def _parse_kv(filepath):
    items = []
    try:
        with open(filepath, "r", encoding="utf-8", errors="replace") as f:
            for line in f:
                line = line.rstrip("\n")
                stripped = line.strip()
                if not stripped:
                    continue

                if stripped.startswith("#") or stripped.startswith(";"):
                    m = _KV_COMMENT_EQ_RE.match(line) or _KV_COMMENT_VAL_RE.match(line)
                    if m and _is_config_key(m.group(1), active=False):
                        items.append({
                            "key": m.group(1),
                            "value": m.group(2),
                            "active": False,
                        })
                    continue

                m = _KV_EQ_RE.match(stripped)
                if m and _is_config_key(m.group(1), active=True):
                    items.append({"key": m.group(1), "value": m.group(2), "active": True})
                    continue

                m = _KV_SPACE_RE.match(stripped)
                if m and _is_config_key(m.group(1), active=True):
                    items.append({"key": m.group(1), "value": m.group(2), "active": True})
                    continue

                m = _SECTION_RE.match(stripped)
                if m:
                    continue
    except IOError:
        pass
    return items


def _is_config_key(key, active=True):
    if len(key) < 2:
        return False
    if " " in key:
        return False
    if not active:
        has_sep = "-" in key or "_" in key or "." in key
        if not has_sep:
            return False
        return True
    if key[0].isupper() and "-" not in key and "_" not in key:
        return False
    return True


def compare_configs(old_files, new_files, old_root, new_root):
    old_map = {f["relpath"]: f for f in old_files}
    new_map = {f["relpath"]: f for f in new_files}
    all_keys = sorted(set(old_map.keys()) | set(new_map.keys()))

    diff_rows = []
    seq = 0

    for relpath in all_keys:
        if relpath not in old_map:
            seq += 1
            nf = new_map[relpath]
            new_items = parse_config(nf["path"], nf["format"])
            if nf["format"] in ("nginx", "apache", "postgresql"):
                diff_rows.append([seq, relpath, "新增配置文件(需AI)", "", "", "", nf["format"]])
            else:
                for item in new_items:
                    seq += 1
                    diff_rows.append([seq, relpath, "新增配置项", item["key"], "",
                                      item["value"], "新增" if item["active"] else "新增(注释)"])
            continue

        if relpath not in new_map:
            seq += 1
            of = old_map[relpath]
            if of["format"] in ("nginx", "apache", "postgresql"):
                diff_rows.append([seq, relpath, "删除配置文件(需AI)", "", "", "", of["format"]])
            else:
                old_items = parse_config(of["path"], of["format"])
                for item in old_items:
                    seq += 1
                    diff_rows.append([seq, relpath, "删除配置项", item["key"],
                                      item["value"], "", "删除" if item["active"] else "删除(注释)"])
            continue

        of = old_map[relpath]
        nf = new_map[relpath]

        if of["format"] in ("nginx", "apache", "postgresql") or nf["format"] in ("nginx", "apache", "postgresql"):
            try:
                old_text = open(of["path"], "r", encoding="utf-8", errors="replace").read()
                new_text = open(nf["path"], "r", encoding="utf-8", errors="replace").read()
                if old_text == new_text:
                    continue
                fmt = nf["format"] if nf["format"] in ("nginx", "apache", "postgresql") else of["format"]
                seq += 1
                diff_rows.append([seq, relpath, "配置文件变更(需AI)", "", "", "", fmt])
            except IOError:
                pass
            continue

        old_items = parse_config(of["path"], of["format"])
        new_items = parse_config(nf["path"], nf["format"])

        old_kv = {}
        for item in old_items:
            key = item["key"]
            old_kv[key] = item

        new_kv = {}
        for item in new_items:
            key = item["key"]
            new_kv[key] = item

        old_keys = set(old_kv.keys())
        new_keys = set(new_kv.keys())

        for key in sorted(new_keys - old_keys):
            seq += 1
            ni = new_kv[key]
            status = "新增" if ni["active"] else "新增(注释)"
            diff_rows.append([seq, relpath, "新增配置项", key, "", ni["value"], status])

        for key in sorted(old_keys - new_keys):
            seq += 1
            oi = old_kv[key]
            status = "删除" if oi["active"] else "删除(注释)"
            diff_rows.append([seq, relpath, "删除配置项", key, oi["value"], "", status])

        for key in sorted(old_keys & new_keys):
            oi = old_kv[key]
            ni = new_kv[key]

            if oi["active"] and not ni["active"]:
                seq += 1
                diff_rows.append([seq, relpath, "状态变更", key, "活跃", "注释",
                                  f"值: {oi['value']} → {ni['value']}"])
            elif not oi["active"] and ni["active"]:
                seq += 1
                diff_rows.append([seq, relpath, "状态变更", key, "注释", "活跃",
                                  f"值: {oi['value']} → {ni['value']}"])
            elif oi["value"] != ni["value"]:
                seq += 1
                if not oi["active"] and not ni["active"]:
                    change_type = "默认值变更"
                else:
                    change_type = "值变更"
                diff_rows.append([seq, relpath, change_type, key,
                                  oi["value"], ni["value"], ""])

    return diff_rows


DIFF_COLS = ["序号", "配置文件", "变更类型", "配置项", "旧版值", "新版值", "说明"]
SINGLE_COLS = ["序号", "配置文件", "格式", "配置项", "值", "状态"]


def write_diff_csv(diff_rows, output_path):
    with open(output_path, "w", newline="", encoding="utf-8-sig") as f:
        w = csv.writer(f, quoting=csv.QUOTE_NONNUMERIC)
        w.writerow(DIFF_COLS)
        for r in diff_rows:
            w.writerow(r)

        ai_items = [r for r in diff_rows if "需AI" in str(r[2])]
        added_items = sum(1 for r in diff_rows if "新增配置项" in str(r[2]))
        removed_items = sum(1 for r in diff_rows if "删除配置项" in str(r[2]))
        value_changed = sum(1 for r in diff_rows if "值变更" in str(r[2]))
        default_changed = sum(1 for r in diff_rows if "默认值变更" in str(r[2]))
        status_changed = sum(1 for r in diff_rows if "状态变更" in str(r[2]))
        new_files = sum(1 for r in diff_rows if "新增配置文件" in str(r[2]))
        removed_files = sum(1 for r in diff_rows if "删除配置文件" in str(r[2]))
        ai_files = sum(1 for r in diff_rows if "配置文件变更(需AI)" in str(r[2]))

        w.writerow([])
        w.writerow(["【统计摘要】"])
        w.writerow(["指标", "数量"])
        w.writerow(["新增配置文件", new_files])
        w.writerow(["删除配置文件", removed_files])
        w.writerow(["新增配置项", added_items])
        w.writerow(["删除配置项", removed_items])
        w.writerow(["值变更", value_changed])
        w.writerow(["默认值变更", default_changed])
        w.writerow(["状态变更(注释↔活跃)", status_changed])
        w.writerow(["需AI分析", len(ai_items) + ai_files])
        w.writerow(["差异合计", len(diff_rows)])

    print(f"✅ 配置差异报告: {output_path} ({len(diff_rows)} 项差异)")


def write_single_csv(files, output_path, label=""):
    with open(output_path, "w", newline="", encoding="utf-8-sig") as f:
        w = csv.writer(f, quoting=csv.QUOTE_NONNUMERIC)
        w.writerow(SINGLE_COLS)
        seq = 0
        for cf in files:
            fmt = cf["format"]
            items = parse_config(cf["path"], fmt)
            if not items and fmt not in ("nginx", "apache", "postgresql"):
                seq += 1
                w.writerow([seq, cf["relpath"], fmt, "(空文件)", "", ""])
                continue
            for item in items:
                seq += 1
                status = "活跃" if item["active"] else "注释"
                w.writerow([seq, cf["relpath"], fmt, item["key"], item["value"], status])
            if not items:
                seq += 1
                w.writerow([seq, cf["relpath"], fmt, "(需AI分析)", "", ""])

        w.writerow([])
        w.writerow(["【统计摘要】"])
        w.writerow(["指标", "数量"])
        w.writerow(["配置文件数", len(files)])

        fmt_counts = {}
        for cf in files:
            fmt_counts[cf["format"]] = fmt_counts.get(cf["format"], 0) + 1
        for fmt_name, cnt in sorted(fmt_counts.items()):
            w.writerow([f"  {fmt_name}", cnt])

        ai_count = sum(1 for cf in files if cf["format"] in ("nginx", "apache", "postgresql"))
        if ai_count:
            w.writerow(["需AI分析的文件", ai_count])

    prefix = f"{label} " if label else ""
    print(f"✅ {prefix}配置文件清单: {output_path} ({len(files)} 个文件)")


def main():
    parser = argparse.ArgumentParser(
        description="运行时配置文件差异分析",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog=__doc__,
    )
    parser.add_argument("dirs", nargs="+",
                        help="项目根目录（1个=单版本，2个=两版本对比）")
    parser.add_argument("-o", "--output", default="config_diff.csv",
                        help="输出文件")
    parser.add_argument("--conf-dirs", default="",
                        help="额外的配置目录名，逗号分隔（默认 conf,etc,config）")
    parser.add_argument("--discover-only", action="store_true",
                        help="只发现配置文件，不解析内容")
    parser.add_argument("--names", default="",
                        help="只分析指定文件名，逗号分隔")
    parser.add_argument("--exclude-dirs", default="",
                        help="跳过指定目录，逗号分隔（默认不排除）")
    args = parser.parse_args()

    dirs = args.dirs
    two_versions = len(dirs) >= 2

    if two_versions:
        old_root = os.path.abspath(dirs[0])
        new_root = os.path.abspath(dirs[1])

        print("━" * 50)
        print("📦 旧版本配置文件发现")
        print("━" * 50)
        old_files = discover_config_files(old_root, args.conf_dirs, args.exclude_dirs)
        print(f"   发现 {len(old_files)} 个配置文件")

        print()
        print("━" * 50)
        print("📦 新版本配置文件发现")
        print("━" * 50)
        new_files = discover_config_files(new_root, args.conf_dirs, args.exclude_dirs)
        print(f"   发现 {len(new_files)} 个配置文件")

        if args.names:
            wanted = set(n.strip() for n in args.names.split(",") if n.strip())
            old_files = [f for f in old_files if os.path.basename(f["path"]) in wanted]
            new_files = [f for f in new_files if os.path.basename(f["path"]) in wanted]

        base, ext = os.path.splitext(args.output)
        old_csv = f"{base}_old{ext}"
        new_csv = f"{base}_new{ext}"

        write_single_csv(old_files, old_csv, "旧版本")
        write_single_csv(new_files, new_csv, "新版本")

        if not args.discover_only:
            diff = compare_configs(old_files, new_files, old_root, new_root)
            write_diff_csv(diff, args.output)
        else:
            print("ℹ️  --discover-only 模式，跳过解析和对比")

    else:
        root = os.path.abspath(dirs[0])
        print(f"📂 扫描配置文件: {root}")
        files = discover_config_files(root, args.conf_dirs, args.exclude_dirs)
        print(f"   发现 {len(files)} 个配置文件")

        if args.names:
            wanted = set(n.strip() for n in args.names.split(",") if n.strip())
            files = [f for f in files if os.path.basename(f["path"]) in wanted]

        if args.discover_only:
            write_discover_csv(files, args.output)
        else:
            write_single_csv(files, args.output)


def write_discover_csv(files, output_path):
    with open(output_path, "w", newline="", encoding="utf-8-sig") as f:
        w = csv.writer(f, quoting=csv.QUOTE_NONNUMERIC)
        w.writerow(["序号", "相对路径", "格式", "大小(KB)", "优先级"])
        for i, cf in enumerate(files, 1):
            size = os.path.getsize(cf["path"]) / 1024
            w.writerow([i, cf["relpath"], cf["format"], f"{size:.1f}", cf["priority"]])

        w.writerow([])
        w.writerow(["【统计摘要】"])
        w.writerow(["指标", "数量"])
        w.writerow(["配置文件总数", len(files)])

        fmt_counts = {}
        for cf in files:
            fmt_counts[cf["format"]] = fmt_counts.get(cf["format"], 0) + 1
        for fmt_name, cnt in sorted(fmt_counts.items()):
            w.writerow([f"  {fmt_name}", cnt])

    print(f"✅ 配置文件发现: {output_path} ({len(files)} 个文件)")


if __name__ == "__main__":
    main()
